INSERT INTO prompts(user_id,category_id,title,description,content,usage_example,output_example,visibility,status) SELECT @author,id,'ออกแบบแผนการสอนเชิงรุก','ข้อมูลสาธิต: ออกแบบแผนการสอนเชิงรุก ปรับตัวแปรให้เหมาะกับงานของคุณ','ออกแบบแผนการสอนเรื่อง [หัวข้อ] สำหรับนักเรียน [ระดับชั้น] เวลา [ระยะเวลา] ระบุเป้าหมาย กิจกรรมที่ผู้เรียนลงมือทำ และเกณฑ์ประเมิน จัดแผนเป็นช่วงเวลาอย่างชัดเจน','กรอกข้อมูลในวงเล็บเหลี่ยมให้ครบ แล้วคัดลอกข้อความไปใช้กับเครื่องมือ AI','ตัวอย่างโครงผลลัพธ์ (ข้อมูลสาธิต): สรุปเป้าหมาย → ขั้นตอนดำเนินการ → ข้อควรตรวจสอบ','public','published' FROM categories WHERE name='การศึกษาและการสอน';
