INSERT INTO prompts(user_id,category_id,title,description,content,usage_example,output_example,visibility,status) SELECT @author,id,'วางโครงรายงานวิเคราะห์','ข้อมูลสาธิต: วางโครงรายงานวิเคราะห์ ปรับตัวแปรให้เหมาะกับงานของคุณ','สร้างโครงรายงานวิเคราะห์เพื่อช่วยตอบคำถาม [คำถามธุรกิจ] จากชุดข้อมูล [รายละเอียดข้อมูล] ระบุตัวชี้วัด วิธีทำความสะอาดข้อมูล และกราฟที่เหมาะสม ห้ามสร้างตัวเลขผลลัพธ์เอง','กรอกข้อมูลในวงเล็บเหลี่ยมให้ครบ แล้วคัดลอกข้อความไปใช้กับเครื่องมือ AI','ตัวอย่างโครงผลลัพธ์ (ข้อมูลสาธิต): สรุปเป้าหมาย → ขั้นตอนดำเนินการ → ข้อควรตรวจสอบ','public','published' FROM categories WHERE name='การวิเคราะห์ข้อมูล';
