INSERT INTO prompts(user_id,category_id,title,description,content,usage_example,output_example,visibility,status) SELECT @author,id,'จัดลำดับงานประจำวัน','ข้อมูลสาธิต: จัดลำดับงานประจำวัน ปรับตัวแปรให้เหมาะกับงานของคุณ','ช่วยจัดลำดับรายการงาน [รายการงาน] ภายในเวลา [เวลาที่มี] ให้พิจารณาความสำคัญ กำหนดส่ง และพลังงานที่ต้องใช้ พร้อมแบ่งช่วงพักอย่างเหมาะสม','กรอกข้อมูลในวงเล็บเหลี่ยมให้ครบ แล้วคัดลอกข้อความไปใช้กับเครื่องมือ AI','ตัวอย่างโครงผลลัพธ์ (ข้อมูลสาธิต): สรุปเป้าหมาย → ขั้นตอนดำเนินการ → ข้อควรตรวจสอบ','public','published' FROM categories WHERE name='งานทั่วไป';
