INSERT INTO prompts(user_id,category_id,title,description,content,usage_example,output_example,visibility,status) SELECT @author,id,'ระดมไอเดียกิจกรรมทีม','ข้อมูลสาธิต: ระดมไอเดียกิจกรรมทีม ปรับตัวแปรให้เหมาะกับงานของคุณ','เสนอไอเดียกิจกรรมสำหรับทีม [จำนวนคน] ภายใต้งบ [งบประมาณ] และข้อจำกัด [ข้อจำกัด] ให้ 5 ทางเลือกพร้อมเวลา อุปกรณ์ และวิธีประเมินผล','กรอกข้อมูลในวงเล็บเหลี่ยมให้ครบ แล้วคัดลอกข้อความไปใช้กับเครื่องมือ AI','ตัวอย่างโครงผลลัพธ์ (ข้อมูลสาธิต): สรุปเป้าหมาย → ขั้นตอนดำเนินการ → ข้อควรตรวจสอบ','public','published' FROM categories WHERE name='งานทั่วไป';
